		if (len != s->size) {
			return -EINVAL;
		}

		int ret = read_cb(cb_arg, (uint8_t *)&m_app_config + s->off, len);

		if (ret < 0) {
			LOG_ERR("Call `read_cb` failed: %d", ret);
			return ret;
		}

		return 0;
